import numpy as np

def vasicek_mean(r0, kappa, theta, t):
    """theta + (r0 - theta) e^(-kappa t), for an array t."""
    t = np.asarray(t, dtype=float)
    return theta + (r0 - theta) * np.exp(-kappa * t)

def half_life(kappa):
    """ln 2 / kappa; ValueError when kappa <= 0."""
    if kappa <= 0:
        raise ValueError("no reversion, so no half-life")
    return float(np.log(2) / kappa)

def time_to_reach(r0, kappa, theta, target):
    """Time for the mean path to reach target; ValueError if it never does."""
    if kappa <= 0 or r0 == theta:
        raise ValueError("the path never moves towards theta")
    ratio = (target - theta) / (r0 - theta)
    if not (0 < ratio <= 1):
        raise ValueError("target is not between r0 and theta")
    return float(-np.log(ratio) / kappa)
